}
function amountAfter(s: string, labels: string) {
  return deNum(
    s.match(
      new RegExp(
        `(?:${labels})\\s*(?:(?:[:=]|beträgt|ist|von)\\s*)?([\\d.]+(?:,\\d{1,2})?)\\s*€?`,
        "i",
      ),
    )?.[1],
