    s.match(/([\d.,]+)\s*(?:Zimmer|Zi\.?)(?:\b|\s)/i)?.[1] ??
      s.match(/(?:Zimmer|Zi\.?)\s*[:]?\s*([\d.,]+)/i)?.[1],
  );
