export function strongUrl(u: string) {
  return /\/expose\/|\/immobilie\/|\/property\/|\/room\/|\/s-anzeige\/|\/tauschangebot\/|\/rent-listing\/|\/immodetail\/|\/wohnung-mieten\//i.test(
    u,
