}
export async function fetchJson(url: string, init: RequestInit = {}) {
  const r = await fetchProvider(url, {
    redirect: "follow",
    ...init,
    headers: {
      "user-agent": UA,
      accept: "application/json",
      ...(init.headers || {}),
    },
    signal: AbortSignal.timeout(12000),
  }, SUPABASE_URL);
