}
function attr(tag: string, name: string) {
  return (
    tag.match(new RegExp(`\\b${name}\\s*=\\s*["']([^"']+)["']`, "i"))?.[1] ||
    null
  );
}
function htmlImages(html: string, base: string) {
  const out: string[] = [];
  for (const m of html.matchAll(/<(?:img|source)\b[^>]*>/gi)) {
    const tag = m[0];
    for (const n of [
