        ) || undefined,
      url: u,
      title: (title || fallbackTitle)?.slice(0, 240) || null,
      address: typeof v.address === 'string' && v.address.trim() ? v.address : address
        ? zip
          ? `${address}, ${zip} ${city && /hamburg/i.test(city) ? city : "Hamburg"}`
          : address
