      } catch {
        requests++;
      }
    }
  cands = [...new Map(cands.map((x) => [x.key || x.url, x])).values()];
  if (!cands.length)
    throw new Error(
      "SAGA public provider index returned no verified Hamburg rental apartments",
    );
