      title:title.slice(0,240),
      address:addr.address,
      zip:addr.zip,
      warm:fields.warm,
      cold:fields.cold,
      additional:fields.additional,
      operating:fields.operating,
      heating:fields.heating,
      deposit:fields.deposit,
      rooms:fields.rooms,
      area:fields.area,
      wbs:fields.wbs,
